package ru.ivan.evrangetest;
import android.app.*;import android.app.job.*;import android.content.*;import org.json.*;
public final class MonitorService extends JobService {
 private static final int JOB=1141;private volatile boolean stopped;
 static boolean enabled(Context c){return c.getSharedPreferences("monitor",0).getBoolean("enabled",false);}
 static boolean enable(Context c,String id){NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("car_changes","Изменения автомобиля",NotificationManager.IMPORTANCE_DEFAULT));JobInfo j=new JobInfo.Builder(JOB,new ComponentName(c,MonitorService.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setPeriodic(15*60*1000L).build();boolean ok=c.getSystemService(JobScheduler.class).schedule(j)==JobScheduler.RESULT_SUCCESS;if(ok)c.getSharedPreferences("monitor",0).edit().clear().putBoolean("enabled",true).putString("car",id).apply();return ok;}
 static void disable(Context c){c.getSystemService(JobScheduler.class).cancel(JOB);c.getSharedPreferences("monitor",0).edit().clear().apply();}
 @Override public boolean onStartJob(JobParameters p){stopped=false;new Thread(()->{try{check();}finally{if(!stopped)jobFinished(p,false);}},"ev-check").start();return true;}
 @Override public boolean onStopJob(JobParameters p){stopped=true;return true;}
 private void check(){android.content.SharedPreferences pref=getSharedPreferences("monitor",0);if(!enabled(this))return;try{JSONObject root;synchronized(TelemetryClient.LOCK){TelemetryClient api=new TelemetryClient(this);api.load();root=RangeData.result(api.readAuthorized("https://mobile-api.technotrek.ru/car/"+pref.getString("car","1141")+"/info"));}JSONObject s=root==null?null:root.optJSONObject("sensors");long now=System.currentTimeMillis()/1000;if(s==null||!RangeData.fresh(RangeData.number(s,"last_online"),now))throw new Exception();if(stopped||!enabled(this))return;
 JSONObject snap=Changes.snapshot(s);String old=pref.getString("baseline","");String changes=old.isEmpty()?"":Changes.compare(new JSONObject(old),snap);if(!changes.isEmpty()){String time=new java.text.SimpleDateFormat("dd.MM HH:mm",new java.util.Locale("ru")).format(new java.util.Date((long)(RangeData.number(s,"last_online")*1000)));notifyUser(changes+"\nПоследняя связь: "+time+". Изменения обнаружены при проверке; время событий неизвестно.");}
 pref.edit().putString("baseline",snap.toString()).putBoolean("failed",false).apply();
 }catch(Exception e){if(!stopped&&enabled(this)&&!pref.getBoolean("failed",false)){notifyUser("Не удалось проверить автомобиль: нет свежих данных или доступа. Это не означает отсутствие изменений. Откройте приложение и обновите показания.");pref.edit().putBoolean("failed",true).apply();}}}
 private void notifyUser(String text){NotificationHistory.add(this,text);NotificationManager n=getSystemService(NotificationManager.class);if(!n.areNotificationsEnabled())return;PendingIntent tap=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(1141,new Notification.Builder(this,"car_changes").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Evolute i-Pro").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(tap).setAutoCancel(true).build());}
}
